"""Check that a non-empty CODEOWNERS file exists."""

import os

CODEOWNERS_PATHS = (
    os.path.join(".github", "CODEOWNERS"),
    os.path.join("docs", "CODEOWNERS"),
    "CODEOWNERS",
)


def check(root: str) -> dict:
    for rel in CODEOWNERS_PATHS:
        path = os.path.join(root, rel)
        if os.path.isfile(path):
            content = open(path, encoding="utf-8", errors="replace").read()
            if content.strip():
                return {"status": "pass", "detail": "%s is present and non-empty" % rel}
            return {"status": "fail", "detail": "%s exists but is empty" % rel}
    return {"status": "fail", "detail": "no CODEOWNERS file found (.github/, docs/, or repo root)"}

