"""Check that the README declares a security contact line.

The README must contain a line starting with ``Security-Contact:``.
"""

import os

README_NAMES = ("README.md", "README.rst", "README.txt", "README")
PREFIX = "security-contact:"


def check(root: str) -> dict:
    readme = next(
        (n for n in README_NAMES if os.path.isfile(os.path.join(root, n))),
        None,
    )
    if readme is None:
        return {"status": "fail", "detail": "no README file found at repo root"}

    path = os.path.join(root, readme)
    with open(path, encoding="utf-8", errors="replace") as fh:
        for line in fh:
            if line.strip().lower().startswith(PREFIX):
                return {
                    "status": "pass",
                    "detail": "%s declares a security contact" % readme,
                }
    return {
        "status": "fail",
        "detail": "%s has no line starting with 'Security-Contact:'" % readme,
    }

