"""Check that CI workflows reference a test command (pytest or npm test)."""

import os

WORKFLOW_DIR = os.path.join(".github", "workflows")
MARKERS = ("pytest", "npm test")


def check(root: str) -> dict:
    wf_dir = os.path.join(root, WORKFLOW_DIR)
    if not os.path.isdir(wf_dir):
        return {"status": "fail", "detail": "no .github/workflows directory found"}

    yml_files = sorted(
        n for n in os.listdir(wf_dir) if n.endswith((".yml", ".yaml"))
    )
    if not yml_files:
        return {"status": "fail", "detail": ".github/workflows contains no yml files"}

    for name in yml_files:
        path = os.path.join(wf_dir, name)
        content = open(path, encoding="utf-8", errors="replace").read()
        for marker in MARKERS:
            if marker in content:
                return {
                    "status": "pass",
                    "detail": "%s runs '%s'" % (path.replace(root + os.sep, ""), marker),
                }
    return {
        "status": "fail",
        "detail": "none of the %d workflow file(s) mention pytest or npm test" % len(yml_files),
    }

